269	    @Override
270	    @Transactional
271	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
272	        boolean isCreate = owner.isNew();
273	        assertTelephoneIsUnique(owner);
274	        if (owner.isNew()) {
275	            assertCityHasCapacity(owner);
276	        }
277	        if (owner.isNew() && !sharesHousehold) {
278	            assertHouseholdIsUnique(owner);
279	        }
280	        if (owner.getRegistrationDate() == null) {
281	            owner.setRegistrationDate(LocalDate.now());
282	        }
283	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
284	        if (owner.isNew()) {
285	            assertDailyRegistrationLimit(owner);
286	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
287	        }
288	        if (owner.isNew() && owner.getCustomerCode() == null) {
289	            owner.setCustomerCode(generateCustomerCode(owner));
290	        }
291	        if (owner.isNew() && owner.getNamesakeCount() == null) {
292	            owner.setNamesakeCount(countNamesakes(owner));
293	        }
294	        ownerRepository.save(owner);
295	        if (isCreate) {
296	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
297	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
298	        }
299	    }
300	
301	    /**
302	     * Count the existing owners that, at the moment this owner is created, share its first name
303	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
304	     * it never counts itself. This value is deterministic given the current data, so it is computed
305	     * once at creation time and stored.
306	     */
307	    private Integer countNamesakes(Owner owner) {
308	        String firstName = owner.getFirstName();
309	        String lastName = owner.getLastName();
310	        if (firstName == null || lastName == null) {
311	            return 0;
312	        }
313	        return (int) ownerRepository.findAll().stream()
314	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
315	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
316	                && lastName.equalsIgnoreCase(existing.getLastName()))
317	            .count();
318	    }
319	
320	    /**
321	     * Build an owner's {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where
322	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
323	     * upper-cased first three letters of the last name, and {@code NNNN} a per-city, 4-digit
324	     * zero-padded sequence equal to one more than the number of owners already in that city
325	     * (e.g. {@code 'LON-SMI-0007'}).
326	     */
327	    private String generateCustomerCode(Owner owner) {
328	        String city = owner.getCity();
329	        String city3 = codePrefix(city);
330	        String last3 = codePrefix(owner.getLastName());
331	        long sequence = ownerRepository.findAll().stream()
332	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
333	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
334	            .count() + 1L;
335	        return String.format("%s-%s-%04d", city3, last3, sequence);
336	    }
337	
338	    /**
339	     * Build a {@code customerCode} segment from {@code value}: its first three characters
340	     * (fewer if it is shorter), upper-cased.
341	     */
342	    private static String codePrefix(String value) {
343	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
344	    }
345	
346	    /**
347	     * Enforce that an owner's normalized telephone is not already used by any <em>other</em>
348	     * owner, throwing {@link DuplicateTelephoneException} if it is. The owner being saved is
349	     * excluded by id so updating an owner in place does not conflict with itself.
350	     */
351	    private void assertTelephoneIsUnique(Owner owner) {
352	        String normalized = Owner.normalizeTelephone(owner.getTelephone());
353	        if (normalized == null) {
354	            return;
355	        }
356	        boolean duplicate = ownerRepository.findAll().stream()
357	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
358	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
359	            .anyMatch(normalized::equals);
360	        if (duplicate) {
361	            throw new DuplicateTelephoneException(normalized);
362	        }
363	    }
364	
365	    /**
366	     * Enforce that no <em>other</em> owner already shares this owner's household, i.e. has the same
367	     * last name (compared case-insensitively with collapsed whitespace, see
368	     * {@link Owner#normalizeHousehold(String)}) and the same normalized address (see
369	     * {@link Owner#normalizeAddress(String)}), throwing {@link DuplicateHouseholdException} if one
370	     * does. The owner being saved is excluded by id. Callers skip this check when the request opted
371	     * in with {@code sharesHousehold}.
372	     */
373	    private void assertHouseholdIsUnique(Owner owner) {
374	        String lastName = Owner.normalizeHousehold(owner.getLastName());
375	        String address = Owner.normalizeAddress(owner.getAddress());
376	        if (lastName == null || address == null) {
377	            return;
378	        }
379	        boolean duplicate = ownerRepository.findAll().stream()
380	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
381	            .anyMatch(existing -> lastName.equals(Owner.normalizeHousehold(existing.getLastName()))
382	                && address.equals(Owner.normalizeAddress(existing.getAddress())));
383	        if (duplicate) {
384	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
385	        }
386	    }
387	
388	    /**
389	     * Enforce that the owner's city has not yet reached its capacity, throwing
390	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
391	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
392	     */
393	    private void assertCityHasCapacity(Owner owner) {
394	        String city = owner.getCity();
395	        if (city == null) {
396	            return;
397	        }
398	        long count = ownerRepository.findAll().stream()
399	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
400	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
401	            .count();
402	        if (count >= MAX_OWNERS_PER_CITY) {
403	            throw new CityAtCapacityException(city);
404	        }
405	    }
406	
407	    /**
408	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
409	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
410	     * the effective registration date (whether supplied in the request or defaulted to the server
411	     * date) so that every value derived from it&mdash;such as the membership number's year segment
412	     * and the daily create-limit counting&mdash;uses the adjusted business day.
413	     */
414	    private static LocalDate rollToBusinessDay(LocalDate date) {
415	        if (date == null) {
416	            return null;
417	        }
418	        DayOfWeek dayOfWeek = date.getDayOfWeek();
419	        if (dayOfWeek == DayOfWeek.SATURDAY) {
420	            return date.plusDays(2);
421	        }
422	        if (dayOfWeek == DayOfWeek.SUNDAY) {
423	            return date.plusDays(1);
424	        }
425	        return date;
426	    }
427	
428	    /**
429	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
430	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
431	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
432	     * is excluded by id.
433	     */
434	    private void assertDailyRegistrationLimit(Owner owner) {
435	        LocalDate registrationDate = owner.getRegistrationDate();
436	        if (registrationDate == null) {
437	            return;
438	        }
439	        long count = ownerRepository.findAll().stream()
440	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
441	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
442	            .count();
443	        if (count >= MAX_OWNERS_PER_DAY) {
444	            throw new DailyRegistrationLimitException(registrationDate);
445	        }
446	    }
447	
448	    /**
449	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
450	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
451	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
452	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
453	     * stored on the owner.
454	     */
455	    private boolean computeBulkSignupWarning(Owner owner) {
456	        LocalDate registrationDate = owner.getRegistrationDate();
457	        if (registrationDate == null) {
458	            return false;
459	        }
460	        long count = ownerRepository.findAll().stream()
461	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
462	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
463	            .count();
464	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
465	    }
466	
467	    @Override
468	    @Transactional(readOnly = true)
469	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
470	        return ownerRepository.findByLastName(lastName);
471	    }
472	
473	    @Override
474	    @Transactional(readOnly = true)
475	    public Collection<Visit> findVisitsByPetId(int petId) {
476	        return visitRepository.findByPetId(petId);
477	    }
478	
479	    @Override
480	    @Transactional(readOnly = true)
481	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
482	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
483	    }
484	
485	    private <T> T findEntityById(Supplier<T> supplier) {
486	        try {
487	            return supplier.get();
488	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
489	            // Just ignore not found exceptions for Jdbc/Jpa realization
490	            return null;
491	        }
492	    }
493	
494	}
